//! Native Full input validation plus read-only funded-original diagnosis.
//! Fixture provenance is generated by the core production preparation test.
#![allow(warnings)]
use super::*;
use kaspa_consensus_core::{
    hashing::{
        sighash::{Mldsa87SigHashReusedValuesUnsync, calc_mldsa87_signature_hash},
        sighash_type::SIG_HASH_ALL,
    },
    mass::MassCalculator,
    palw_court_original_escrow_v1::{COURT_ORIGINAL_FUNDING_SIGNATURE_CONTEXT_V1, FundingConsentV1, FundingTermsV1},
    palw_state_v2::{PalwFundedOriginalCandidateV1, PalwStateCarriageV2, PalwStateParamsV2},
    palw_tir_funded_original_envelope_v1::PalwTirFundedOriginalEnvelopeV1,
    palw_tir_public_fp_envelope_v1::PalwTirPublicFpEnvelopeV1,
    tx::{PopulatedTransaction, TransactionInput, TransactionOutput, UtxoEntry},
    utxo::utxo_collection::UtxoCollection,
};
use kaspa_txscript::{MLDSA87_TX_CONTEXT, script_builder::ScriptBuilder};
use libcrux_ml_dsa::ml_dsa_87 as mldsa;

/// Ordinary UTXO script validation and escrow qualification are independent
/// requirements. This self-contained test uses real payer signatures and the
/// production fee schedule, without a captured chain or an ignored campaign.
#[tokio::test]
async fn funded_escrow_real_native_signatures_payment_burn_continuation_and_refund() {
    use crate::pipeline::virtual_processor::utxo_validation::PalwEscrowSpendLocksV1;
    use kaspa_consensus_core::palw_funded_escrow_v1 as escrow;
    let config = ConfigBuilder::new(MAINNET_PARAMS).skip_proof_of_work().build();
    let ctx = TestContext::new(TestConsensus::new(&config));
    let vp = ctx.consensus.virtual_processor();
    let keypair = mldsa::generate_key_pair([0x74; 32]);
    let key = keypair.verification_key.as_ref().to_vec();
    let address = kaspa_hashes::blake2b_512_address_payload(&key);
    let spk = kaspa_consensus_core::mldsa87_primitives::p2pkh_mldsa87_spk(&address.as_bytes());
    let h = kaspa_hashes::Hash64::from_u64_word;
    let mut row = escrow::PalwFundedEscrowRowV1::fresh_v1(
        h(1),
        h(2),
        TransactionOutpoint::new(h(3), 0),
        2_000_000_000,
        kaspa_consensus_core::mldsa87_primitives::mldsa87_key_id(&key),
        address,
        100,
        10_100,
        true,
    )
    .unwrap();
    row.fee_sompi = 1_000_000_000;
    row.seat_payee = address;
    row.relay_payee = address;
    let [work, relay, burn] = kaspa_consensus_core::palw_g14_values_v1::palw_g14_escrow_split_v1(row.fee_sompi);
    let remainder = row.amount_sompi - row.fee_sompi;
    let entry = UtxoEntry::new(row.amount_sompi, spk.clone(), 0, false);
    let sign = |tx: &mut Transaction, entries: Vec<UtxoEntry>| {
        tx.set_mass(
            MassCalculator::new(0, 0, 0, config.params.storage_mass_parameter)
                .calc_contextual_masses(&PopulatedTransaction::new(tx, entries.clone()))
                .unwrap()
                .storage_mass,
        );
        let reused = Mldsa87SigHashReusedValuesUnsync::new();
        for input in 0..tx.inputs.len() {
            let hash = calc_mldsa87_signature_hash(&PopulatedTransaction::new(tx, entries.clone()), input, SIG_HASH_ALL, &reused);
            let mut signature = mldsa::sign(&keypair.signing_key, hash.as_bytes().as_slice(), MLDSA87_TX_CONTEXT, [0x75; 32])
                .unwrap()
                .as_ref()
                .to_vec();
            signature.push(SIG_HASH_ALL.to_u8());
            tx.inputs[input].signature_script = ScriptBuilder::new().add_data(&signature).unwrap().add_data(&key).unwrap().drain();
        }
        tx.finalize();
    };
    let mut spend = Transaction::new(
        crate::constants::TX_VERSION,
        vec![TransactionInput::new(row.funding_outpoint, vec![], 0, 1)],
        vec![
            TransactionOutput::new(work, spk.clone()),
            TransactionOutput::new(relay, spk.clone()),
            TransactionOutput::new(remainder, spk.clone()),
        ],
        0,
        kaspa_consensus_core::subnets::SUBNETWORK_ID_NATIVE,
        0,
        vec![],
    );
    sign(&mut spend, vec![entry.clone()]);
    let view: UtxoCollection = [(row.funding_outpoint, entry.clone())].into_iter().collect();
    let full = crate::processes::transaction_validator::tx_validation_in_utxo_context::TxValidationFlags::Full;
    let validated = vp.validate_transaction_in_utxo_context(&spend, &view, 500, full, None).unwrap();
    assert_eq!(validated.calculated_fee, burn);
    let locks = PalwEscrowSpendLocksV1 { rows: [(row.funding_outpoint, row)].into_iter().collect(), ..Default::default() };
    assert_eq!(locks.refusal(&spend, [row.amount_sompi], 500), None);
    let plan = escrow::palw_escrow_qualified_spend_v1(
        &row,
        &spend,
        &[row.amount_sompi],
        500,
        escrow::palw_escrow_fee_schedule_v1(&row).as_ref(),
    )
    .unwrap();
    assert_eq!((plan.paid_now, plan.burned_now, plan.continued_now), (work + relay, burn, remainder));
    assert_eq!(vp.palw_collectible_transaction_fee_v1(&spend, validated.calculated_fee, plan.burned_now, 500), 0);
    let mut invalid_signature = spend.clone();
    invalid_signature.inputs[0].signature_script[10] ^= 1;
    invalid_signature.finalize();
    assert!(vp.validate_transaction_in_utxo_context(&invalid_signature, &view, 500, full, None).is_err());
    let mut theft = spend.clone();
    theft.outputs[2].value -= 1;
    sign(&mut theft, vec![entry]);
    vp.validate_transaction_in_utxo_context(&theft, &view, 500, full, None).unwrap();
    assert_eq!(locks.refusal(&theft, [row.amount_sompi], 500), Some(row.funding_outpoint));

    // The core sweep's liability-resolution tests cover authorization to clear
    // this flag. Once resolved, the actual current change output is refundable.
    let mut closed = plan.new;
    closed.liability_open = false;
    let continued_entry = UtxoEntry::new(remainder, spk.clone(), 500, false);
    let fee_outpoint = TransactionOutpoint::new(h(4), 0);
    let fee_entry = UtxoEntry::new(100_000_000, spk.clone(), 0, false);
    let mut refund = Transaction::new(
        crate::constants::TX_VERSION,
        vec![TransactionInput::new(closed.funding_outpoint, vec![], 0, 1), TransactionInput::new(fee_outpoint, vec![], 0, 1)],
        vec![TransactionOutput::new(remainder, spk)],
        0,
        kaspa_consensus_core::subnets::SUBNETWORK_ID_NATIVE,
        0,
        vec![],
    );
    sign(&mut refund, vec![continued_entry.clone(), fee_entry.clone()]);
    let view: UtxoCollection = [(closed.funding_outpoint, continued_entry), (fee_outpoint, fee_entry)].into_iter().collect();
    vp.validate_transaction_in_utxo_context(&refund, &view, closed.hard_deadline_daa, full, None).unwrap();
    let returned =
        escrow::palw_escrow_qualified_spend_v1(&closed, &refund, &[remainder, 100_000_000], closed.hard_deadline_daa, None).unwrap();
    assert_eq!(returned.returned_now, remainder);
    assert_eq!(returned.new.paid_sompi + returned.new.burned_sompi + returned.new.returned_sompi, row.amount_sompi);
    assert_eq!(
        escrow::palw_escrow_qualified_spend_v1(&returned.new, &refund, &[remainder, 100_000_000], closed.hard_deadline_daa, None),
        Err(escrow::PalwEscrowRefusalV1::AlreadySettled)
    );
}

#[tokio::test]
async fn palw_funded_original_real_native_inputs_preserve_fallback_and_refuse_incomplete_admission() {
    let dir = std::env::var("MISAKA_G14_NATIVE_FIXTURE_DIR").unwrap_or_else(|_| {
        std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("tests/fixtures/g14-funded-original-native")
            .to_string_lossy()
            .into_owned()
    });
    let read = |name: &str| std::fs::read(std::path::Path::new(&dir).join(name)).unwrap();
    let params: PalwStateParamsV2 = borsh::from_slice(&read("params.borsh")).unwrap();
    let carriage: PalwStateCarriageV2 = borsh::from_slice(&read("state.borsh")).unwrap();
    let state = carriage.into_state(&params, None).unwrap();
    let root = state.state_root();
    let original = PalwTirPublicFpEnvelopeV1::decode_v1(&read("original.tfp1")).unwrap();
    let fp = original.original_fp_v1().unwrap();
    let now: u64 = std::str::from_utf8(&read("accepting-daa.txt")).unwrap().parse().unwrap();
    // Existing native TEST bundle, not a new tariff/production preset. The
    // standalone original state remains the core-generated preparation fixture.
    let catalog = palw_v2_test_catalog();
    let bundle = palw_v2_test_bundle_funded_for(&catalog, 64);
    let config = ConfigBuilder::new(MAINNET_PARAMS)
        .skip_proof_of_work()
        .edit_consensus_params(move |p| {
            p.palw_consensus_mode = kaspa_consensus_core::palw_mode_v2::PalwConsensusMode::ConsensusV2(bundle.clone());
            *p = p.clone().with_palw_v2_cadence();
        })
        .build();
    let ctx = TestContext::new(TestConsensus::new(&config));
    let vp = ctx.consensus.virtual_processor();
    let seed = [0x73; 32]; // Public local fixture only.
    let kp = mldsa::generate_key_pair(seed);
    let key = kp.verification_key.as_ref().to_vec();
    let payer = kaspa_consensus_core::mldsa87_primitives::mldsa87_key_id(&key);
    let address = kaspa_hashes::blake2b_512_address_payload(&key);
    assert_ne!(payer, address, "key identity and native address use distinct hash domains");
    let spk = kaspa_consensus_core::mldsa87_primitives::p2pkh_mldsa87_spk(&address.as_bytes());
    let h = |n| kaspa_hashes::Hash64::from_u64_word(n);
    let mut consent = FundingConsentV1 {
        terms: FundingTermsV1 {
            version: 1,
            network_domain: vp.palw_network_domain_v2(),
            claim: fp.claim_id(),
            job_identity: original.pledge.job_identity,
            execution_root: fp.commitment.execution_root,
            source_id: original.pledge.source_id,
            relative_graph_id: h(2),
            fee_profile_id: h(3),
            capital_profile_id: h(4),
            retention_profile_id: h(5),
            settlement_policy_id: h(6),
            accept_from_daa: now,
            accept_until_daa: now + 100,
            material_until_daa: now + 20_000,
            funding_output_index: 0,
            funding_amount_sompi: 1_000_000_000,
            payer_key_id: payer,
            refund_payload: address,
            nonce: h(7),
        },
        signature: vec![],
    };
    consent.signature =
        mldsa::sign(&kp.signing_key, consent.terms.id_v1().as_byte_slice(), COURT_ORIGINAL_FUNDING_SIGNATURE_CONTEXT_V1, seed)
            .unwrap()
            .as_ref()
            .to_vec();
    let envelope = PalwTirFundedOriginalEnvelopeV1::new_v1(original.encode_v1().unwrap(), consent, key.clone()).unwrap();
    let previous = TransactionOutpoint::new(h(0xF135), 0);
    let value = 2_000_000_000;
    let entry = UtxoEntry::new(value, spk.clone(), 0, false);
    let sign = |tx: &mut Transaction, previous_entry: &UtxoEntry| {
        let mass = MassCalculator::new(0, 0, 0, config.params.storage_mass_parameter)
            .calc_contextual_masses(&PopulatedTransaction::new(tx, vec![previous_entry.clone()]))
            .unwrap()
            .storage_mass;
        tx.set_mass(mass);
        let hash = calc_mldsa87_signature_hash(
            &PopulatedTransaction::new(tx, vec![previous_entry.clone()]),
            0,
            SIG_HASH_ALL,
            &Mldsa87SigHashReusedValuesUnsync::new(),
        );
        let mut item = mldsa::sign(&kp.signing_key, hash.as_bytes().as_slice(), MLDSA87_TX_CONTEXT, seed).unwrap().as_ref().to_vec();
        item.push(SIG_HASH_ALL.to_u8());
        tx.inputs[0].signature_script = ScriptBuilder::new().add_data(&item).unwrap().add_data(&key).unwrap().drain();
        tx.finalize();
    };
    let make = |payload: Vec<u8>| {
        let mut tx = Transaction::new(
            crate::constants::TX_VERSION,
            vec![TransactionInput::new(previous, vec![], 0, 1)],
            vec![TransactionOutput::new(envelope.funding.terms.funding_amount_sompi, spk.clone())],
            0,
            kaspa_consensus_core::subnets::SUBNETWORK_ID_PALW_FP_COMMITMENT,
            0,
            payload,
        );
        sign(&mut tx, &entry);
        tx
    };
    let view: UtxoCollection = [(previous, entry.clone())].into_iter().collect();
    let full = crate::processes::transaction_validator::tx_validation_in_utxo_context::TxValidationFlags::Full;
    let tx = make(envelope.encode_v1().unwrap());
    let validated = vp.validate_transaction_in_utxo_context(&tx, &view, now, full, None).unwrap();
    let diagnostic = vp.palw_funded_original_candidate_from_native_v1(&state, now, &validated);
    assert!(
        matches!(&diagnostic,PalwFundedOriginalCandidateV1::Missing(s) if s.starts_with("native source checked;")),
        "{diagnostic:?}"
    );
    assert_eq!(state.state_root(), root);
    assert!(state.claim(&fp.claim_id()).is_none());
    assert_eq!(validated.calculated_fee, value - envelope.funding.terms.funding_amount_sompi);
    {
        use crate::{
            model::stores::{
                acceptance_data::AcceptanceDataStore, block_transactions::BlockTransactionsStore, ghostdag::GhostdagData,
            },
            pipeline::virtual_processor::{
                processor::palw_accept::bind_accepted_tfp1_history_v1, utxo_validation::UtxoProcessingContext,
            },
        };
        use kaspa_consensus_core::{
            dns_finality::ActiveBondView, palw_funded_original_coordinator_v1::palw_funded_original_pairing_v1,
            palw_state_v2::PalwBlockContextV2, palw_tir_funded_original_envelope_v3::PalwTirFundedOriginalEnvelopeV3,
            subnets::SUBNETWORK_ID_NATIVE,
        };
        use misaka_palw_positive_contract::public_one_honest::SignedPublicOriginalV1;

        // Only the framing of this dummy companion is exercised. The real
        // TFP1, payer consent and both normal UTXO spends remain signed.
        let companion = [0x42; SignedPublicOriginalV1::WIRE_BYTES];
        let wire =
            PalwTirFundedOriginalEnvelopeV3::from_parts_v3(&tx.payload, b"history fixture", &companion).unwrap().encode_v3().unwrap();
        let paired_tx = make(wire);
        let validated_pair = vp.validate_transaction_in_utxo_context(&paired_tx, &view, now, full, None).unwrap();
        assert!(matches!(
            vp.palw_funded_original_candidate_from_native_v1(&state, now, &validated_pair),
            PalwFundedOriginalCandidateV1::Missing(why) if why.contains("complete protected public-original profile")
        ));
        let ordinary_input = TransactionOutpoint::new(h(0xF201), 0);
        let mut ordinary = Transaction::new(
            crate::constants::TX_VERSION,
            vec![TransactionInput::new(ordinary_input, vec![], 0, 1)],
            vec![TransactionOutput::new(value - 1_000_000, spk.clone())],
            0,
            SUBNETWORK_ID_NATIVE,
            0,
            vec![],
        );
        sign(&mut ordinary, &entry);
        let composed: UtxoCollection = [(previous, entry.clone()), (ordinary_input, entry.clone())].into_iter().collect();
        vp.validate_transaction_in_utxo_context(&ordinary, &composed, now, full, None).unwrap();

        // Exercise the native UTXO walk against a test-only stored selected-
        // parent body. This fixture does not insert an accepted PALW claim.
        let selected_parent = h(0xF202);
        let mut body = config.params.genesis.build_genesis_transactions();
        let coinbase = body[0].id();
        body.extend([ordinary.clone(), paired_tx.clone()]);
        vp.block_transactions_store.insert(selected_parent, body.into()).unwrap();
        let ghostdag = GhostdagData::new_with_selected_parent(selected_parent, 0);
        let at = PalwBlockContextV2 { block: h(0xF203), daa_score: now, blue_score: now + 1, subsidy: 0 };
        let mut accepted = UtxoProcessingContext::new((&ghostdag).into(), kaspa_muhash::MuHash::new());
        accepted.palw_tfp1_history_accepting_point_v1 = Some(at);
        vp.calculate_utxo_state_with_tokenizer_v1(&mut accepted, &composed, &ActiveBondView::default(), now, Some(&state), None)
            .unwrap();
        assert_eq!(accepted.accepted_tx_ids, [coinbase, ordinary.id(), paired_tx.id()]);
        assert_eq!(accepted.palw_tfp1_history_seeds_v1.len(), 1);
        let history = &accepted.palw_tfp1_history_seeds_v1[&paired_tx.id()];
        assert_eq!(history.selected_parent, selected_parent);
        assert_eq!(history.origin.accepting_block.0, at.block.as_bytes());
        assert_eq!(history.origin.accepted_daa, at.daa_score);
        assert_eq!(history.origin.accepted_blue_score, at.blue_score);
        assert_eq!(history.origin.accepted_tx_ordinal, 2);
        assert_eq!(history.origin.event_ordinal, 0);
        vp.acceptance_data_store.insert(at.block, accepted.mergeset_acceptance_data.clone().into()).unwrap();
        let (archived_block, archived_tx, _) = vp
            .acceptance_data_store
            .accepted_origin_at_bounded_v2(at.block, history.origin.accepted_tx_ordinal, 4_096)
            .unwrap()
            .unwrap();
        assert_eq!(archived_block.as_bytes(), history.origin.carrier_block.0);
        assert_eq!(archived_tx.transaction_id.as_bytes(), history.origin.carrier_transaction.0);
        assert_eq!(archived_tx.index_within_block, 2);

        let mut pairing = palw_funded_original_pairing_v1(&paired_tx).unwrap();
        assert!(bind_accepted_tfp1_history_v1(&mut pairing, &accepted.palw_tfp1_history_seeds_v1, h(0xF204), now).is_err());
        bind_accepted_tfp1_history_v1(&mut pairing, &accepted.palw_tfp1_history_seeds_v1, at.block, now).unwrap();
        assert_eq!(pairing.carrier().id(), paired_tx.id());
        let wrong_ordinal = misaka_palw_positive_contract::rows::AcceptedOrigin { accepted_tx_ordinal: 1, ..history.origin };
        assert!(pairing.bind_history_inputs_v1(history.inputs, wrong_ordinal, selected_parent).is_err());

        let mut preview = UtxoProcessingContext::new((&ghostdag).into(), kaspa_muhash::MuHash::new());
        preview.positive_relay_preview_point = Some(at);
        vp.calculate_utxo_state_with_tokenizer_v1(&mut preview, &composed, &ActiveBondView::default(), now, Some(&state), None)
            .unwrap();
        assert_eq!(preview.accepted_tx_ids, accepted.accepted_tx_ids);
        assert!(preview.palw_tfp1_history_seeds_v1.is_empty());
        assert_eq!(state.state_root(), root);
        assert!(state.claim(&fp.claim_id()).is_none());
    }
    // Read-only outer accounting carrier: actual funding signatures authenticate FPA1 bytes,
    // while the inner payer consent still authenticates its own unchanged TFO1 terms.
    let answer = vec![0; fp.commitment.decode_tokens_executed as usize];
    let wire =
        kaspa_consensus_core::palw_fp_answer_accounting_v1::palw_fp_answer_envelope_retain_encode_v1(&tx.payload, &answer).unwrap();
    let accounting_tx = make(wire.to_vec());
    assert_ne!(accounting_tx.id(), tx.id());
    let accounting_validated = vp.validate_transaction_in_utxo_context(&accounting_tx, &view, now, full, None).unwrap();
    let court = vp.palw_court_params_at(now).and_then(Result::ok);
    let native = court.as_ref().map(|c| (c, vp.palw_court_step_ladder_at(now, c)));
    let accounting_diagnostic = kaspa_consensus_core::palw_state_v2::palw_funded_original_answer_candidate_v1(
        &state,
        vp.palw_network_domain_v2(),
        now,
        &accounting_validated,
        vp.palw_state_params_v2.as_ref(),
        native,
    );
    assert!(
        matches!(&accounting_diagnostic,PalwFundedOriginalCandidateV1::Missing(s) if s.starts_with("native source checked;")),
        "{accounting_diagnostic:?}"
    );
    assert_eq!(accounting_validated.calculated_fee, validated.calculated_fee);
    assert_eq!(accounting_tx.outputs, tx.outputs);
    assert_eq!(state.state_root(), root);
    assert!(state.claim(&fp.claim_id()).is_none());
    // Full native inputs and payer consent stay valid. Corrupt ONLY the
    // producer's separate source pledge signature, keeping its signed scope,
    // original FP commitment, funding profile IDs/output/amount unchanged.
    let mut bad_source_envelope = envelope.clone();
    let mut bad_source_original = bad_source_envelope.original_v1().unwrap();
    bad_source_original.pledge.signature[0] ^= 1;
    bad_source_envelope.original_envelope = bad_source_original.encode_v1().unwrap();
    bad_source_envelope.funding.verify_signature_v1(&bad_source_envelope.payer_pubkey).unwrap();
    bad_source_envelope
        .original_v1()
        .unwrap()
        .original_fp_v1()
        .unwrap()
        .validate_signature_v3(kaspa_consensus_core::palw_constraint_stream_carriage_v1::palw_staged_verify_mldsa87_v1)
        .unwrap();
    let bad_source = make(bad_source_envelope.encode_v1().unwrap());
    let bad_source_validated = vp.validate_transaction_in_utxo_context(&bad_source, &view, now, full, None).unwrap();
    assert_eq!(bad_source_validated.calculated_fee, validated.calculated_fee);
    assert_eq!(
        vp.palw_funded_original_candidate_from_native_v1(&state, now, &bad_source_validated),
        PalwFundedOriginalCandidateV1::Invalid("current producer source pledge signature")
    );
    assert_eq!(bad_source.outputs, tx.outputs);
    assert_eq!(state.state_root(), root);
    assert!(state.claim(&fp.claim_id()).is_none());
    // Unknown profiles in the signed consent never create funded standing.
    // The ordinary own output remains spendable with the actual payer signature.
    let fallback = TransactionOutpoint::new(tx.id(), 0);
    let fallback_entry = UtxoEntry::new(tx.outputs[0].value, tx.outputs[0].script_public_key.clone(), now, false);
    let mut spend = Transaction::new(
        crate::constants::TX_VERSION,
        vec![TransactionInput::new(fallback, vec![], 0, 1)],
        vec![TransactionOutput::new(tx.outputs[0].value - 1, spk.clone())],
        0,
        kaspa_consensus_core::subnets::SUBNETWORK_ID_NATIVE,
        0,
        vec![],
    );
    sign(&mut spend, &fallback_entry);
    let fallback_view: UtxoCollection = [(fallback, fallback_entry)].into_iter().collect();
    vp.validate_transaction_in_utxo_context(&spend, &fallback_view, now + 1, full, None).unwrap();
    // An ordinary valid carrier may pay a trap script, but it must NEVER be
    // recognized as a payer-recoverable funded-original fallback.
    let mut trap = tx.clone();
    trap.outputs[0].script_public_key = kaspa_consensus_core::mldsa87_primitives::p2pkh_mldsa87_spk(&payer.as_bytes());
    sign(&mut trap, &entry);
    assert!(trap.id_is_current(), "trap must reach output authentication, not stale-id refusal");
    envelope.funding.verify_signature_v1(&envelope.payer_pubkey).unwrap();
    let actual_trap = kaspa_consensus_core::palw_court_original_escrow_v1::inspect_transaction_v1(&trap, 0).unwrap();
    assert_eq!(
        envelope.funding.check_actual_output_v1(&actual_trap, &envelope.payer_pubkey),
        Err(kaspa_consensus_core::palw_court_original_escrow_v1::FundingRefusalV1::OutputMismatch)
    );
    let trap_validated = vp.validate_transaction_in_utxo_context(&trap, &view, now, full, None).unwrap();
    assert_eq!(
        vp.palw_funded_original_candidate_from_native_v1(&state, now, &trap_validated),
        PalwFundedOriginalCandidateV1::Invalid("actual funding output or payer consent signature")
    );
    assert_eq!(state.state_root(), root);
    let mut bad = tx.clone();
    bad.inputs[0].signature_script[10] ^= 1;
    assert!(vp.validate_transaction_in_utxo_context(&bad, &view, now, full, None).is_err());
    assert!(vp.validate_transaction_in_utxo_context(&tx, &UtxoCollection::default(), now, full, None).is_err());
    assert!(matches!(
        vp.palw_funded_original_candidate_from_native_v1(&state, now + 101, &validated),
        PalwFundedOriginalCandidateV1::Invalid(_)
    ));
    let mut replaced = PalwStateCarriageV2::from_state(&state);
    let replaced_bond =
        replaced.bonds.get_mut(&kaspa_consensus_core::palw_state_v2::PalwBondKeyV2(fp.commitment.job.executor_bond)).unwrap();
    replaced_bond.pubkey = key.clone();
    replaced_bond.operator_id = kaspa_consensus_core::palw_state_v2::palw_operator_id_v2(&key);
    let replaced = replaced.into_state(&params, None).unwrap();
    assert!(matches!(
        vp.palw_funded_original_candidate_from_native_v1(&replaced, now, &validated),
        PalwFundedOriginalCandidateV1::Invalid(_)
    ));
    // The original was generated and prepared with this public TEST producer
    // key. Mutations below remain real MLDSA signed carrier transactions.
    let producer_seed = [0x6D; 32];
    let producer_key = mldsa::generate_key_pair(producer_seed);
    assert_eq!(producer_key.verification_key.as_ref(), fp.commitment.job.executor_pubkey.as_slice());
    let mutate_pledge = |source: Option<kaspa_consensus_core::Hash64>, expiry: Option<u64>| {
        let mut candidate = envelope.clone();
        let mut original = candidate.original_v1().unwrap();
        if let Some(source) = source {
            original.pledge.source_id = source;
            candidate.funding.terms.source_id = source;
        }
        if let Some(expiry) = expiry {
            original.pledge.accept_until_daa = expiry;
        }
        original.pledge.signature = mldsa::sign(
            &producer_key.signing_key,
            original.pledge.id_v1().as_byte_slice(),
            kaspa_consensus_core::palw_tir_public_custody_v1::PALW_TIR_SOURCE_PLEDGE_CONTEXT_V1,
            producer_seed,
        )
        .unwrap()
        .as_ref()
        .to_vec();
        candidate.original_envelope = original.encode_v1().unwrap();
        candidate.funding.signature = mldsa::sign(
            &kp.signing_key,
            candidate.funding.terms.id_v1().as_byte_slice(),
            COURT_ORIGINAL_FUNDING_SIGNATURE_CONTEXT_V1,
            seed,
        )
        .unwrap()
        .as_ref()
        .to_vec();
        make(candidate.encode_v1().unwrap())
    };
    assert!(now > 1, "fixture must span a real registration/acceptance boundary");
    for (candidate, reason) in [
        (mutate_pledge(Some(h(0xF136)), None), "producer pledge differs from actual native source"),
        (mutate_pledge(None, Some(now - 1)), "producer source pledge acceptance clock"),
    ] {
        let actual = vp.validate_transaction_in_utxo_context(&candidate, &view, now, full, None).unwrap();
        assert_eq!(
            vp.palw_funded_original_candidate_from_native_v1(&state, now, &actual),
            PalwFundedOriginalCandidateV1::Invalid(reason)
        );
        assert_eq!(candidate.outputs, tx.outputs);
        assert_eq!(actual.calculated_fee, validated.calculated_fee);
        assert_eq!(state.state_root(), root);
    }
    // Real current state metadata is authoritative, not the signed profile IDs.
    let mut future = PalwStateCarriageV2::from_state(&state);
    future.classes.get_mut(&fp.commitment.job.class_id).unwrap().registered_daa = now + 1;
    let future = future.into_state(&params, None).unwrap();
    assert_eq!(
        vp.palw_funded_original_candidate_from_native_v1(&future, now, &validated),
        PalwFundedOriginalCandidateV1::Invalid("native registered class time or artifact")
    );
    let mut foreign = PalwStateCarriageV2::from_state(&state);
    foreign.classes.get_mut(&fp.commitment.job.class_id).unwrap().artifact_root = h(0xF137);
    let foreign = foreign.into_state(&params, None).unwrap();
    assert_eq!(
        vp.palw_funded_original_candidate_from_native_v1(&foreign, now, &validated),
        PalwFundedOriginalCandidateV1::Invalid("native registered class time or artifact")
    );
    let mut geometry = PalwStateCarriageV2::from_state(&state);
    let layout_key = kaspa_consensus_core::palw_staged_court_state_v1::PalwStagedCourtKeyV1::TirLayout(fp.commitment.job.class_id);
    if let kaspa_consensus_core::palw_staged_court_state_v1::PalwStagedCourtRowV1::TirLayout(layout) =
        geometry.staged_courts.get_mut(&layout_key).unwrap()
    {
        assert!(!layout.commit_tiles.is_empty());
        layout.commit_tiles[0] = if layout.commit_tiles[0] == 4 { 8 } else { 4 };
    } else {
        panic!("actual registered layout fixture");
    }
    let geometry = geometry.into_state(&params, None).unwrap();
    assert_eq!(
        vp.palw_funded_original_candidate_from_native_v1(&geometry, now, &validated),
        PalwFundedOriginalCandidateV1::Invalid("native original source geometry or job roots")
    );
    // Explicit local TEST configuration mutation only; no preset/fence is armed
    // in production. Resolve demand at registered DAA, NOT accepting DAA.
    // Reuse the existing runnable T12 launch rule chain (audit, k-ary,
    // R-core+ and its complete prerequisites), never assemble a half-ruleset by
    // switching on TIR over the deliberately minimal baseline TEST bundle.
    let (known_valid, _, _, _) = super::t12_round_lane_e2e::t12_with_harness_cards();
    let mut demand_config = known_valid.params.clone();
    demand_config.palw_tir_v1 = Some(kaspa_consensus_core::palw_tir_v1::PalwTirFenceV1::testnet12_v1(
        kaspa_consensus_core::config::params::ForkActivation::new(0),
    ));
    demand_config.sync_palw_tir_v1();
    demand_config.palw_tir_fence2 = Some(kaspa_consensus_core::config::params::ForkActivation::new(1));
    demand_config.sync_palw_tir_fence2();
    let demand_config = ConfigBuilder::new(demand_config).skip_proof_of_work().build();
    let demand_ctx = TestContext::new(TestConsensus::new(&demand_config));
    let demand_vp = demand_ctx.consensus.virtual_processor();
    // Funding consent belongs to the ACTUAL T12 network, independently of the
    // baseline MAINNET fixture. Re-sign rather than forge a matching domain.
    assert_ne!(demand_vp.palw_network_domain_v2(), vp.palw_network_domain_v2());
    assert_eq!(
        demand_config.params.storage_mass_parameter, config.params.storage_mass_parameter,
        "reusing make/sign requires the same actual native storage mass parameter"
    );
    let mut demand_envelope = envelope.clone();
    demand_envelope.funding.terms.network_domain = demand_vp.palw_network_domain_v2();
    demand_envelope.funding.signature = mldsa::sign(
        &kp.signing_key,
        demand_envelope.funding.terms.id_v1().as_byte_slice(),
        COURT_ORIGINAL_FUNDING_SIGNATURE_CONTEXT_V1,
        seed,
    )
    .unwrap()
    .as_ref()
    .to_vec();
    demand_envelope.funding.verify_signature_v1(&demand_envelope.payer_pubkey).unwrap();
    let demand_tx = make(demand_envelope.encode_v1().unwrap());
    let actual = demand_vp.validate_transaction_in_utxo_context(&demand_tx, &view, now, full, None).unwrap();
    assert_eq!(actual.calculated_fee, validated.calculated_fee);
    assert_eq!(demand_tx.outputs, tx.outputs);
    let mut old = PalwStateCarriageV2::from_state(&state);
    old.classes.get_mut(&fp.commitment.job.class_id).unwrap().registered_daa = 0;
    let old = old.into_state(&params, None).unwrap();
    assert!(matches!(demand_vp.palw_funded_original_candidate_from_native_v1(&old,now,&actual),
        PalwFundedOriginalCandidateV1::Missing(s) if s.contains("registered Release2000 demand")));
    let mut newer = PalwStateCarriageV2::from_state(&state);
    newer.classes.get_mut(&fp.commitment.job.class_id).unwrap().registered_daa = 1;
    let newer = newer.into_state(&params, None).unwrap();
    assert!(matches!(demand_vp.palw_funded_original_candidate_from_native_v1(&newer,now,&actual),
        PalwFundedOriginalCandidateV1::Missing(s) if s.contains("registered H7 demand")));
    // The actual configured court/ladder is used by native source construction.
    // A smaller TEST court cannot be replaced by a producer's signed hash.
    assert_eq!(state.class_step_ladder_v1(&fp.commitment.job.class_id, 2), 2, "fixture has no held uplift");
    let mut small_config = config.params.clone();
    if let kaspa_consensus_core::palw_mode_v2::PalwConsensusMode::ConsensusV2(bundle) = &mut small_config.palw_consensus_mode {
        // Change only the tested leaf ladder. Preserve the court's existing
        // clock, terminal rounds and cost ceilings, including its state mirror.
        let actual = bundle.court;
        bundle.court = kaspa_consensus_core::palw_mode_v2::PalwCourtParamsV2::with_cost_ceilings(
            2,
            actual.turn_deadline_daa(),
            actual.terminal_rounds(),
            actual.max_close_bytes(),
            actual.max_terminal_macs(),
            actual.max_operand_count(),
        )
        .unwrap();
        assert_eq!(bundle.court.dissection_arity(), actual.dissection_arity());
    } else {
        panic!("native fixture consensus-v2 policy");
    }
    // A dormant ladder fence MUST retain the historical executor cap.
    let dormant_config = ConfigBuilder::new(small_config.clone()).skip_proof_of_work().build();
    let dormant_ctx = TestContext::new(TestConsensus::new(&dormant_config));
    let dormant_vp = dormant_ctx.consensus.virtual_processor();
    let actual = dormant_vp.validate_transaction_in_utxo_context(&tx, &view, now, full, None).unwrap();
    assert!(matches!(dormant_vp.palw_funded_original_candidate_from_native_v1(&state,now,&actual),
        PalwFundedOriginalCandidateV1::Missing(s) if s.starts_with("native source checked;")));
    // Only the explicit TEST fence makes the configured two-leaf ladder apply.
    small_config.palw_court_ladder = Some(kaspa_consensus_core::config::params::ForkActivation::always());
    let small_config = ConfigBuilder::new(small_config).skip_proof_of_work().build();
    let small_ctx = TestContext::new(TestConsensus::new(&small_config));
    let small_vp = small_ctx.consensus.virtual_processor();
    let actual = small_vp.validate_transaction_in_utxo_context(&tx, &view, now, full, None).unwrap();
    assert_eq!(
        small_vp.palw_funded_original_candidate_from_native_v1(&state, now, &actual),
        PalwFundedOriginalCandidateV1::Invalid("native original source geometry or job roots")
    );
    assert_eq!(tx.outputs.len(), 1);
    assert_eq!(state.state_root(), root);
    assert!(state.claim(&fp.claim_id()).is_none());
    for payload in [b"TFO1".to_vec(), {
        let mut bad = envelope.clone();
        bad.funding.signature[0] ^= 1;
        bad.encode_v1().unwrap()
    }] {
        let bad = make(payload);
        let accepted = vp.validate_transaction_in_utxo_context(&bad, &view, now, full, None).unwrap();
        assert!(matches!(
            vp.palw_funded_original_candidate_from_native_v1(&state, now, &accepted),
            PalwFundedOriginalCandidateV1::Invalid(_)
        ));
        assert_eq!(state.state_root(), root);
    }
}
